//! `scriptvox licenses` (PLAN-R1 D8): the third-party notices travel inside the
//! binary. `licenses/THIRD_PARTY.md` is generated by cargo-about (`just
//! notices`); a test fails when its crate list is stale.

pub const THIRD_PARTY: &str = include_str!("../../../licenses/THIRD_PARTY.md");
pub const OFL: &str = include_str!("../../../LICENSES/OFL-1.1.txt");
/// The GPL text. The Kokoro plugin is GPL-3.0-or-later, and the FFmpeg build is too: a user gets the text with them.
pub const GPL: &str = include_str!("../../../LICENSES/GPL-3.0-or-later.txt");
/// `group, name, version, licence as PyPI states it`, one per package of the worker and the plugins.
const PYTHON: &str = include_str!("../../../licenses/python-packages.tsv");

