/// The Python packages, one object each.
pub fn python_packages() -> Vec<serde_json::Value> {
    PYTHON
        .lines()
        .filter(|l| !l.starts_with('#'))
        .filter_map(|l| {
            let c: Vec<&str> = l.split('\t').collect();
            Some(serde_json::json!({"group": c.first()?, "name": c.get(1)?, "version": c.get(2)?, "license": c.get(3)?}))
        })
        .collect()
}

/// Every file that setup can download: the tools, the weights, the tokenizers and the voice packs, each with its own licence.
pub fn downloads() -> Vec<serde_json::Value> {
    crate::provision::pins()
        .into_iter()
        .filter(|p| p.target == crate::provision::target() || p.target == "any")
        .map(|p| serde_json::json!({"name": p.name, "version": p.version, "license": p.licence, "url": p.url, "bytes": p.size}))
        .collect()
}

/// `name version` of every crate in the notices.
pub fn crates() -> Vec<String> {
    let mut v: Vec<String> = THIRD_PARTY
        .lines()
        .filter_map(|l| l.strip_prefix("Used by: "))
        .flat_map(|l| l.split(", "))
        .map(|s| s.trim().to_string())
        .collect();
    v.sort();
    v.dedup();
    v
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_locked_python_package_has_a_licence_row() {
        let rows = super::python_packages();
        for (group, lock) in [
            ("worker", include_str!("../../../python/uv.lock")),
            ("kokoro", include_str!("../../../plugins/kokoro/uv.lock")),
            ("whisper", include_str!("../../../plugins/whisper/uv.lock")),
        ] {
            let doc: toml::Table = toml::from_str(lock).unwrap();
            for p in doc["package"].as_array().unwrap() {
                if p.get("source")
                    .is_some_and(|s| s.get("virtual").is_some() || s.get("editable").is_some())
                {
                    continue;
                }
                let (n, v) = (p["name"].as_str().unwrap(), p["version"].as_str().unwrap());
                assert!(
                    rows.iter()
                        .any(|r| r["group"] == group && r["name"] == n && r["version"] == v),
                    "{group} {n} {v} has no row: run scripts/python-licences.py"
                );
            }
        }
    }

    #[test]
    fn the_gpl_text_and_each_kind_of_download_are_listed() {
        assert!(
            super::GPL.contains("GNU GENERAL PUBLIC LICENSE") && super::GPL.contains("Version 3")
        );
        let names: Vec<String> = super::downloads()
            .iter()
            .map(|d| d["name"].as_str().unwrap().to_string())
            .collect();
        for want in ["kokoro-voices", "whisper-small-tokenizer", "klein-4b-dit"] {
            assert!(names.iter().any(|n| n == want), "{want}: {names:?}");
        }
    }
}
